class Produk{
    constructor(nama, harga, stok){        
        this.nama = nama;
        this.harga = parseInt(harga);
        this.stok = parseInt(stok);
        this.kurir = 'Standard';
    }
}

class Order {
    constructor(userId, totalHarga, metodeBayar){
        this.userId = userId;
        this.totalHarga = parseInt(totalHarga); // Pengubahan dari string ke integer
        this.metodeBayar = metodeBayar;
        this.items = [];
    }

    addToCart(produk, jumlah) {
        if (jumlah > this.stok) {
            console.log(`Maaf, stock produk ${produk.nama} tidak cukup untuk ditambahkan.`);
            return;
        }

        if (this.items.length === 0) {
            this.items.push({...produk, jumlah: jumlah});
        } else {
            let index = -1;
            for (let i = 0; i < this.items.length; i++) {
                if (this.items[i].nama === produk.nama) {
                    index = i;
                    break;
                }
            }
            if (index !== -1) {
                this.items[index].jumlah += jumlah;
            } else {
                this.items.push({...produk, jumlah: jumlah});
            }
        }
    }

    hitungTotalHarga() {
        let total = 0;
        this.items.forEach(item => {
            total += item.harga * item.jumlah;
        });
        return total;
    }

    setMetodeBayar(metode) {
        if (metode === 'Credit Card' || metode === 'Bank Transfer') {
            this.metodeBayar = metode;
        } else {
            throw new Error('Metode pembayaran harus berupa Credit Card atau Bank Transfer.');
        }
    }

    render() {
        console.log('\n=== Pesanan Anda ===');
        console.log(`Nama Pelanggan: ${this.userId}`);
        console.log(`Total Harga: Rp ${this.totalHarga.toLocaleString()}`);
        console.log(`Metode Pembayaran: ${this.metodeBayar}`);
        console.log("Item Keranjang:");
        this.items.forEach((item, i) => {
            console.log(`${i + 1}. ${item.nama} x${item.jumlah} = Rp ${(item.harga * item.jumlah).toLocaleString()}`);
        });
        console.log("\nThank you for your purchase!");
    }
}

// Contoh penggunaan:
const user_id = 123;
const order = new Order(user_id, 100000, 'Credit Card');

const produk1 = new Produk('Semangka', 5000, 10);
const produk2 = new Produk('Apel', 3000, 15);
const produk3 = new Produk('Durian', 8000, 20);

order.addToCart(produk1, 2);
order.addToCart(produk2, 5);
order.addToCart(produk3, 1);

console.log(`Jumlah Total: Rp ${order.hitungTotalHarga().toLocaleString()}`);



