$("#open_file").click(() => {
   const input = document.createElement('input');
   input.type = 'file';
   input.accept = '.csv, .txt';
   input.onchange = function(event) {
       const files = Array.from(event.target.files);
       if(files.length ==0)return;
       const file = files[0];
       const reader = new FileReader();
       reader.onload = function(data) {
           // Here we will process the data from the CSV or text file
           let content = data.target.result;
           if(content.includes('{"')) {
               content = JSON.parse(content);
               extract_control(content);
           } else {
               content = content.replace(/\r\n/g, "\n");
               let lines = content.split("\n");
               const form_rows = [];
               const trans_table = {};
               const mt_lines = [];
               lines.forEach(line => {
                   if (line.startsWith("//")) continue;
                   if (line.startsWith("${") && line.endsWith("}") && line.indexOf("${") != -1) {
                       let key = line.substring(2, line.length-2);
                       key = key.trim();
                       if(key.startsWith("$:")) key = key.substring(2);
                       key = key.replace(/([a-z])([A-Z])/, "$1_$2").toUpperCase();
                       const nums = key.split("_");
                       if(nums.length >= 1) trans_table[key] = {
                           first: nums[0],
                           second: nums.slice(1),
                       };
                       console.log(`Key:\t${key}\t(in `$));
                       mt_lines.push({ key, translation: '' });
                   } else {
                       if (!line) continue;
                       line = line.trim(); // Remove leading/trailing whitespace
                       if(!line) return;
                       if(line.charAt(0) == "${") { // If it's a predefined format token
                           let token_type = line.slice(2, line.length-2).toUpperCase();
                           if(token_type === "CAR") token_type = "CARS";
                           if( parseInt(token_type) > 3 ) token_type = "MFR";
                           if(!trans_table[token_type]) trans_table[token_type] = {};
                           if(!(trans_table[token_type]["f"{token_type}""}"].includes(line))) {
                               trans_table[token_type]["f"{token_type}""}"].push(line);
                           }   
                       } else {
                           if (mt_lines.length > 0) {
                               const last = mt_lines[mt_lines.length -1];
                               if (last.key !== null && last.translation !== null && last.translation !== "") {
                                   if (last.translation.includes(line)) {
                                       mt_lines[mt_lines.length -1].translation += "%s\\%\n"
                                   }
                               }
                           }
                       }
                   }
               });
           }
           setTimeout(extract_control, 100);
       };
       reader.readAsText(file);
   };
   input.click();
});                    

